"""Generate lib/src/variation.dart from the JSON produced by extract_variations.py.

usage: python3 tool/extract_variations.py <dnp3>/src/app/variations.rs vars.json
       python3 tool/gen_variations_rs.py vars.json native/src/variation.rs
       python3 tool/gen_variations_dart.py vars.json lib/src/variation.dart
"""
import json, sys

d = json.load(open(sys.argv[1]))
fx = d['fixed']
L = [
    '// Generated by tool/gen_variations_dart.py from dnp3 1.7.0. Do not edit.',
    '',
    '/// A DNP3 object group / variation pair.',
    'final class Variation {',
    '  /// Object group number',
    '  final int group;',
    '',
    '  /// Variation number within the group (0 = any variation)',
    '  final int variation;',
    '',
    '  /// Description from IEEE 1815 (as named by the dnp3 crate)',
    '  final String description;',
    '',
    '  const Variation._(this.group, this.variation, this.description);',
    '',
    '  /// Device attribute (group 0) with an arbitrary variation',
    "  factory Variation.group0(int variation) => variation == 254 ? group0Var254 : Variation._(0, variation, 'Device Attributes - Specific Attribute');",
    '',
    '  /// Octet string (group 110) sized by variation',
    "  factory Variation.group110(int size) => Variation._(110, size, 'Octet String - Sized by variation');",
    '',
    '  /// Octet string event (group 111) sized by variation',
    "  factory Variation.group111(int size) => Variation._(111, size, 'Octet String Event - Sized by variation');",
    '',
]
for n, g, v, desc in fx:
    name = n[0].lower() + n[1:]
    desc = desc.replace("'", "\\'")
    L.append(f"  /// g{g}v{v}: {desc.replace(chr(92), '')}")
    L.append(f"  static const {name} = Variation._({g}, {v}, '{desc}');")
L += ['', '  /// Every fixed group / variation known to the dnp3 crate', '  static const List<Variation> values = [']
for n, g, v, desc in fx:
    L.append(f"    {n[0].lower() + n[1:]},")
L += ['  ];', '',
      '  static final Map<int, Variation> _byKey = {for (final v in values) (v.group << 8) | v.variation: v};', '',
      '  /// Look up a variation. Groups 0, 110 and 111 accept any variation number.',
      '  static Variation? lookup(int group, int variation) {',
      '    final known = _byKey[(group << 8) | variation];',
      '    if (known != null) return known;',
      '    return switch (group) {',
      '      0 => Variation.group0(variation),',
      '      110 => Variation.group110(variation),',
      '      111 => Variation.group111(variation),',
      '      _ => null,',
      '    };',
      '  }', '',
      '  @override',
      '  bool operator ==(Object other) => other is Variation && other.group == group && other.variation == variation;', '',
      '  @override',
      '  int get hashCode => (group << 8) | variation;', '',
      '  @override',
      "  String toString() => 'g${group}v$variation';",
      '}', '']
open(sys.argv[2], 'w').write('\n'.join(L))
